36	import org.springframework.validation.BindingResult;
37	import org.springframework.validation.FieldError;
38	
39	import static org.assertj.core.api.Assertions.assertThat;
40	import static org.assertj.core.api.Assertions.assertThatThrownBy;
41	import static org.mockito.ArgumentMatchers.any;
42	import static org.mockito.BDDMockito.given;
43	import static org.mockito.Mockito.never;
44	import static org.mockito.Mockito.verify;
45	import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
46	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.flash;
47	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.model;
48	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
49	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.view;
50	
51	/**
52	 * Characterization tests that pin the current validation and save behavior of
53	 * {@link PetController} before it is restructured. They describe what the code does
54	 * today, not necessarily what it should do.
55	 */
56	@WebMvcTest(value = PetController.class,
57			includeFilters = @ComponentScan.Filter(value = PetTypeFormatter.class, type = FilterType.ASSIGNABLE_TYPE))
58	@DisabledInNativeImage
59	@DisabledInAotMode
60	class PetControllerCharacterizationTests {
61	
62		private static final int OWNER_ID = 1;
63	
64		private static final int PETTY_ID = 1;
65	
66		private static final int DOGGY_ID = 2;
67	
68		private static final String FORM = "pets/createOrUpdatePetForm";
69	
70		@Autowired
71		private MockMvc mockMvc;
72	
73		@MockitoBean
74		private OwnerRepository owners;
75	
76		@MockitoBean
77		private PetTypeRepository types;
78	
79		private Owner owner;
80	
81		private Pet petty;
82	
83		private PetType hamster;
84	
85		@BeforeEach
86		void setup() {
87			hamster = new PetType();
88			hamster.setId(3);
89			hamster.setName("hamster");
90			given(this.types.findPetTypes()).willReturn(List.of(hamster));
91	
92			owner = new Owner();
93			petty = new Pet();
94			petty.setId(PETTY_ID);
95			petty.setName("petty");
96			petty.setBirthDate(LocalDate.of(2010, 1, 1));
97			Pet doggy = new Pet();
98			doggy.setId(DOGGY_ID);
99			doggy.setName("doggy");
100			owner.addPet(petty);
101			owner.addPet(doggy);
102			given(this.owners.findById(OWNER_ID)).willReturn(Optional.of(owner));
103		}
104	
105		// ---- create form ----
106	
107		@Test
108		void createSavesOwnerWithNewPetAndFlashesMessage() throws Exception {
109			mockMvc
110				.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("name", "Betty")
111					.param("type", "hamster")
112					.param("birthDate", "2015-02-12"))
113				.andExpect(status().is3xxRedirection())
114				.andExpect(view().name("redirect:/owners/{ownerId}"))
115				.andExpect(flash().attribute("message", "New Pet has been Added"));
116	
117			verify(owners).saveAndFlush(owner);
118			Pet betty = owner.getPet("Betty");
119			assertThat(betty).isNotNull();
120			assertThat(betty.getBirthDate()).isEqualTo(LocalDate.of(2015, 2, 12));
121			assertThat(betty.getType()).isSameAs(hamster);
122			assertThat(owner.getPets()).hasSize(3);
123		}
124	
125		@Test
126		void createAcceptsBirthDateOfToday() throws Exception {
127			mockMvc
128				.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("name", "Betty")
129					.param("type", "hamster")
130					.param("birthDate", LocalDate.now().toString()))
131				.andExpect(status().is3xxRedirection());
132		}
133	
134		@Test
135		void createRejectsBirthDateOfTomorrowWithCodeOnlyAndDoesNotSave() throws Exception {
136			MvcResult result = mockMvc
137				.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("name", "Betty")
138					.param("type", "hamster")
139					.param("birthDate", LocalDate.now().plusDays(1).toString()))
140				.andExpect(status().isOk())
141				.andExpect(view().name(FORM))
142				.andExpect(model().errorCount(1))
143				.andExpect(model().attributeHasFieldErrorCode("pet", "birthDate", "typeMismatch.birthDate"))
144				.andReturn();
145	
146			// SUSPECT: a future date is reported with the parse-error code typeMismatch
147			// and no default message.
148			assertThat(
149					result.getModelAndView().getModel().get("org.springframework.validation.BindingResult.pet").toString())
150				.contains("default message [null]");
151			verify(owners, never()).saveAndFlush(any());
152		}
153	
154		@Test
155		void createMissingBirthDateIsRequired() throws Exception {
156			mockMvc.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("name", "Betty").param("type", "hamster"))
157				.andExpect(status().isOk())
158				.andExpect(model().errorCount(1))
159				.andExpect(model().attributeHasFieldErrorCode("pet", "birthDate", "required"));
160		}
161	
162		@Test
163		void createDuplicateNameIsCaseInsensitive() throws Exception {
164			mockMvc
165				.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("name", "PETTY")
166					.param("type", "hamster")
167					.param("birthDate", "2015-02-12"))
168				.andExpect(status().isOk())
169				.andExpect(model().errorCount(1))
170				.andExpect(model().attributeHasFieldErrorCode("pet", "name", "duplicate"));
171			verify(owners, never()).saveAndFlush(any());
172		}
173	
174		@Test
175		void createDuplicateCheckIgnoresUnsavedPetsOfOwner() throws Exception {
176			Pet unsaved = new Pet();
177			unsaved.setName("Ghost");
178			owner.getPets().add(unsaved);
179	
180			mockMvc
181				.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("name", "ghost")
182					.param("type", "hamster")
183					.param("birthDate", "2015-02-12"))
184				.andExpect(status().is3xxRedirection());
185		}
186	
187		@Test
188		void createBlankNameReportsOnlyRequiredNotDuplicate() throws Exception {
189			mockMvc
190				.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("name", "")
191					.param("type", "hamster")
192					.param("birthDate", "2015-02-12"))
193				.andExpect(model().errorCount(1))
194				.andExpect(model().attributeHasFieldErrorCode("pet", "name", "required"));
195		}
196	
197		@Test
198		void createNameOf30CharsAccepted() throws Exception {
199			mockMvc
200				.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("name", "A".repeat(30))
201					.param("type", "hamster")
202					.param("birthDate", "2015-02-12"))
203				.andExpect(status().is3xxRedirection());
204		}
205	
206		@Test
207		void createNameOf31CharsRejectedWithSize() throws Exception {
208			mockMvc
209				.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("name", "A".repeat(31))
210					.param("type", "hamster")
211					.param("birthDate", "2015-02-12"))
212				.andExpect(status().isOk())
213				.andExpect(model().errorCount(1))
214				.andExpect(model().attributeHasFieldErrorCode("pet", "name", "size"));
215		}
216	
217		@Test
218		void createReportsDuplicateNameAndFutureBirthDateTogether() throws Exception {
219			mockMvc
220				.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("name", "petty")
221					.param("type", "hamster")
222					.param("birthDate", LocalDate.now().plusDays(1).toString()))
223				.andExpect(status().isOk())
224				.andExpect(model().errorCount(2))
225				.andExpect(model().attributeHasFieldErrorCode("pet", "name", "duplicate"))
226				.andExpect(model().attributeHasFieldErrorCode("pet", "birthDate", "typeMismatch.birthDate"));
227		}
228	
229		@Test
230		void createReportsEveryValidatorErrorAtOnce() throws Exception {
231			mockMvc.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("name", ""))
232				.andExpect(status().isOk())
233				.andExpect(model().errorCount(3))
234				.andExpect(model().attributeHasFieldErrorCode("pet", "name", "required"))
235				.andExpect(model().attributeHasFieldErrorCode("pet", "type", "required"))
236				.andExpect(model().attributeHasFieldErrorCode("pet", "birthDate", "required"));
237		}
238	
239		@Test
240		void createUnparseableBirthDateReportsTypeMismatchAndRequired() throws Exception {
241			MvcResult result = mockMvc
242				.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("name", "Betty")
243					.param("type", "hamster")
244					.param("birthDate", "2015/02/12"))
245				.andExpect(status().isOk())
246				.andExpect(model().errorCount(2))
247				.andExpect(model().attributeHasFieldErrorCode("pet", "birthDate", "typeMismatch"))
248				.andReturn();
249			BindingResult errors = (BindingResult) result.getModelAndView()
250				.getModel()
251				.get(BindingResult.MODEL_KEY_PREFIX + "pet");
252			assertThat(errors.getFieldErrors("birthDate")).extracting(FieldError::getCode)
253				.containsExactly("typeMismatch", "required");
254		}
255	
256		@Test
257		void createIgnoresSubmittedId() throws Exception {
258			mockMvc
259				.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("id", "99")
260					.param("name", "Betty")
261					.param("type", "hamster")
262					.param("birthDate", "2015-02-12"))
263				.andExpect(status().is3xxRedirection());
264			assertThat(owner.getPet("Betty").getId()).isNull();
265		}
266	
267		@Test
268		void createUniqueViolationMessageMatchedCaseInsensitively() throws Exception {
269			given(owners.saveAndFlush(any(Owner.class)))
270				.willThrow(new DataIntegrityViolationException("Duplicate key: UNIQUE_OWNER_PET_NAME"));
271			mockMvc
272				.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("name", "Betty")
273					.param("type", "hamster")
274					.param("birthDate", "2015-02-12"))
275				.andExpect(status().isOk())
276				.andExpect(view().name(FORM))
277				.andExpect(model().attributeHasFieldErrorCode("pet", "name", "duplicate"));
278		}
279	
280		@Test
281		void createOtherIntegrityViolationIsRethrown() {
282			given(owners.saveAndFlush(any(Owner.class))).willThrow(new DataIntegrityViolationException("fk_type"));
283			assertThatThrownBy(() -> mockMvc.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("name", "Betty")
284				.param("type", "hamster")
285				.param("birthDate", "2015-02-12"))).hasRootCauseInstanceOf(DataIntegrityViolationException.class);
286		}
287	
288		// ---- edit form ----
289	
290		@Test
291		void editUpdatesExistingPetAndFlashesMessage() throws Exception {
292			mockMvc
293				.perform(post("/owners/{ownerId}/pets/{petId}/edit", OWNER_ID, PETTY_ID).param("name", "Betty")
294					.param("type", "hamster")
295					.param("birthDate", "2015-02-12"))
296				.andExpect(status().is3xxRedirection())
297				.andExpect(view().name("redirect:/owners/{ownerId}"))
298				.andExpect(flash().attribute("message", "Pet details has been edited"));
299	
300			verify(owners).saveAndFlush(owner);
301			assertThat(owner.getPets()).hasSize(2);
302			assertThat(petty.getName()).isEqualTo("Betty");
303			assertThat(petty.getBirthDate()).isEqualTo(LocalDate.of(2015, 2, 12));
304			assertThat(petty.getType()).isSameAs(hamster);
305			assertThat(petty.getId()).isEqualTo(PETTY_ID);
306		}
307	
308		@Test
309		void editCopiesNameBirthDateAndTypeOntoOwnersPetWhenInstancesDiffer() throws Exception {
310			given(this.owners.findById(OWNER_ID)).willAnswer(invocation -> {
311				Owner fresh = new Owner();
312				Pet freshPetty = new Pet();
313				freshPetty.setId(PETTY_ID);
314				freshPetty.setName("petty");
315				freshPetty.setBirthDate(LocalDate.of(2010, 1, 1));
316				fresh.addPet(freshPetty);
317				return Optional.of(fresh);
318			});
319			ArgumentCaptor<Owner> saved = ArgumentCaptor.forClass(Owner.class);
320	
321			mockMvc
322				.perform(post("/owners/{ownerId}/pets/{petId}/edit", OWNER_ID, PETTY_ID).param("name", "Betty")
323					.param("type", "hamster")
324					.param("birthDate", "2015-02-12"))
325				.andExpect(status().is3xxRedirection());
326	
327			verify(owners).saveAndFlush(saved.capture());
328			assertThat(saved.getValue().getPets()).hasSize(1);
329			Pet savedPet = saved.getValue().getPet(PETTY_ID);
330			assertThat(savedPet.getName()).isEqualTo("Betty");
331			assertThat(savedPet.getBirthDate()).isEqualTo(LocalDate.of(2015, 2, 12));
332			assertThat(savedPet.getType()).isSameAs(hamster);
333		}
334	
335		@Test
336		void editDoesNotRequireType() throws Exception {
337			mockMvc
338				.perform(post("/owners/{ownerId}/pets/{petId}/edit", OWNER_ID, PETTY_ID).param("name", "Betty")
339					.param("birthDate", "2015-02-12"))
340				.andExpect(status().is3xxRedirection());
341		}
342	
343		@Test
344		void editAcceptsBirthDateOfToday() throws Exception {
345			mockMvc
346				.perform(post("/owners/{ownerId}/pets/{petId}/edit", OWNER_ID, PETTY_ID).param("name", "Betty")
347					.param("type", "hamster")
348					.param("birthDate", LocalDate.now().toString()))
349				.andExpect(status().is3xxRedirection());
350		}
351	
352		@Test
353		void editMissingBirthDateIsRequiredAndNotSaved() throws Exception {
354			mockMvc
355				.perform(post("/owners/{ownerId}/pets/{petId}/edit", OWNER_ID, PETTY_ID).param("name", "Betty")
