363		}
364	
365		@Test
366		void editDuplicateNameOfOtherPetIsCaseInsensitive() throws Exception {
367			mockMvc
368				.perform(post("/owners/{ownerId}/pets/{petId}/edit", OWNER_ID, DOGGY_ID).param("name", "PETTY")
