376	
377		@Test
378		void editOwnNameInDifferentCaseIsAllowed() throws Exception {
379			mockMvc
380				.perform(post("/owners/{ownerId}/pets/{petId}/edit", OWNER_ID, PETTY_ID).param("name", "PETTY")
