395	
396		@Test
397		void editBlankNameReportsOnlyRequiredNotDuplicate() throws Exception {
398			mockMvc
399				.perform(post("/owners/{ownerId}/pets/{petId}/edit", OWNER_ID, PETTY_ID).param("name", "")
400					.param("birthDate", "2015-02-12"))
401				.andExpect(model().errorCount(1))
402				.andExpect(model().attributeHasFieldErrorCode("pet", "name", "required"));
