421				.perform(post("/owners/{ownerId}/pets/{petId}/edit", OWNER_ID, PETTY_ID).param("id", "99")
422					.param("name", "Betty")
423					.param("birthDate", "2015-02-12"))
424				.andExpect(status().is3xxRedirection());
425			assertThat(petty.getId()).isEqualTo(PETTY_ID);
426		}
427	
428		@Test
429		void editUnknownPetIdFailsWithNullPointerAndDoesNotSave() {
430			// SUSPECT: findPet returns null for an unknown pet, validation is skipped and
431			// isNameTakenByAnotherPet dereferences the null pet. The add-pet branch of
432			// updatePetDetails is never reached from this endpoint.
433			assertThatThrownBy(
434					() -> mockMvc.perform(post("/owners/{ownerId}/pets/{petId}/edit", OWNER_ID, 99).param("name", "Betty")
435						.param("type", "hamster")
436						.param("birthDate", "2015-02-12")))
437				.hasRootCauseInstanceOf(NullPointerException.class);
438			verify(owners, never()).saveAndFlush(any());
439		}
