444				.willThrow(new DataIntegrityViolationException("Duplicate key: UNIQUE_OWNER_PET_NAME"));
445			mockMvc
446				.perform(post("/owners/{ownerId}/pets/{petId}/edit", OWNER_ID, PETTY_ID).param("name", "Betty")
447					.param("birthDate", "2015-02-12"))
448				.andExpect(status().isOk())
449				.andExpect(view().name(FORM))
450				.andExpect(model().attributeHasFieldErrorCode("pet", "name", "duplicate"));
451		}
452	
453		@Test
454		void editOtherIntegrityViolationIsRethrown() {
455			given(owners.saveAndFlush(any(Owner.class))).willThrow(new DataIntegrityViolationException("fk_type"));
456			assertThatThrownBy(() -> mockMvc
457				.perform(post("/owners/{ownerId}/pets/{petId}/edit", OWNER_ID, PETTY_ID).param("name", "Betty")
458					.param("birthDate", "2015-02-12")))
459				.hasRootCauseInstanceOf(DataIntegrityViolationException.class);
460		}
461	
462	}
