16	package org.springframework.samples.petclinic.owner;
17	
18	import java.util.Collection;
19	import java.util.Objects;
20	import java.util.Optional;
21	
22	import org.springframework.dao.DataIntegrityViolationException;
23	import org.springframework.stereotype.Controller;
24	import org.springframework.ui.ModelMap;
25	import org.springframework.util.Assert;
26	import org.springframework.util.StringUtils;
27	import org.springframework.validation.BindingResult;
28	import org.springframework.web.bind.WebDataBinder;
29	import org.springframework.web.bind.annotation.GetMapping;
30	import org.springframework.web.bind.annotation.InitBinder;
31	import org.springframework.web.bind.annotation.ModelAttribute;
32	import org.springframework.web.bind.annotation.PathVariable;
33	import org.springframework.web.bind.annotation.PostMapping;
34	import org.springframework.web.bind.annotation.RequestMapping;
35	
36	import jakarta.validation.Valid;
37	
38	import org.springframework.web.servlet.mvc.support.RedirectAttributes;
39	
40	/**
41	 * @author Juergen Hoeller
42	 * @author Ken Krebs
43	 * @author Arjen Poutsma
44	 * @author Wick Dynex
45	 */
46	@Controller
47	@RequestMapping("/owners/{ownerId}")
48	class PetController {
49	
50		private static final String VIEWS_PETS_CREATE_OR_UPDATE_FORM = "pets/createOrUpdatePetForm";
51	
52		private final OwnerRepository owners;
53	
54		private final PetTypeRepository types;
55	
56		public PetController(OwnerRepository owners, PetTypeRepository types) {
57			this.owners = owners;
58			this.types = types;
59		}
60	
61		@ModelAttribute("types")
62		public Collection<PetType> populatePetTypes() {
63			return this.types.findPetTypes();
64		}
65	
66		@ModelAttribute("owner")
67		public Owner findOwner(@PathVariable("ownerId") int ownerId) {
68			Optional<Owner> optionalOwner = this.owners.findById(ownerId);
69			Owner owner = optionalOwner.orElseThrow(() -> new IllegalArgumentException(
70					"Owner not found with id: " + ownerId + ". Please ensure the ID is correct "));
71			return owner;
72		}
73	
74		@ModelAttribute("pet")
75		public Pet findPet(@PathVariable("ownerId") int ownerId,
76				@PathVariable(name = "petId", required = false) Integer petId) {
77	
78			if (petId == null) {
79				return new Pet();
80			}
81	
82			Optional<Owner> optionalOwner = this.owners.findById(ownerId);
83			Owner owner = optionalOwner.orElseThrow(() -> new IllegalArgumentException(
84					"Owner not found with id: " + ownerId + ". Please ensure the ID is correct "));
85			return owner.getPet(petId);
86		}
87	
88		@InitBinder("owner")
89		public void initOwnerBinder(WebDataBinder dataBinder) {
90			dataBinder.setDisallowedFields("id", "*.id");
91		}
92	
93		@InitBinder("pet")
94		public void initPetBinder(WebDataBinder dataBinder) {
95			dataBinder.setValidator(new PetValidator());
96			dataBinder.setDisallowedFields("id", "*.id");
97		}
98	
99		@GetMapping("/pets/new")
100		public String initCreationForm(Owner owner, ModelMap model) {
101			Pet pet = new Pet();
102			owner.addPet(pet);
103			return VIEWS_PETS_CREATE_OR_UPDATE_FORM;
104		}
105	
106		@PostMapping("/pets/new")
107		public String processCreationForm(Owner owner, @Valid Pet pet, BindingResult result,
108				RedirectAttributes redirectAttributes) {
109	
110			if (StringUtils.hasText(pet.getName()) && pet.isNew() && owner.getPet(pet.getName(), true) != null) {
111				result.rejectValue("name", "duplicate", "already exists");
112			}
113	
114			if (result.hasErrors()) {
115				return VIEWS_PETS_CREATE_OR_UPDATE_FORM;
116			}
117	
118			try {
119				owner.addPet(pet);
120				this.owners.saveAndFlush(owner);
121			}
122			catch (DataIntegrityViolationException ex) {
123				if (!isDuplicatePetNameViolation(ex)) {
124					throw ex;
125				}
126				result.rejectValue("name", "duplicate", "already exists");
127				return VIEWS_PETS_CREATE_OR_UPDATE_FORM;
128			}
129			redirectAttributes.addFlashAttribute("message", "New Pet has been Added");
130			return "redirect:/owners/{ownerId}";
131		}
132	
133		@GetMapping("/pets/{petId}/edit")
134		public String initUpdateForm() {
135			return VIEWS_PETS_CREATE_OR_UPDATE_FORM;
136		}
137	
138		@PostMapping("/pets/{petId}/edit")
139		public String processUpdateForm(Owner owner, @Valid Pet pet, BindingResult result,
140				RedirectAttributes redirectAttributes) {
141	
142			if (isNameTakenByAnotherPet(owner, pet)) {
143				result.rejectValue("name", "duplicate", "already exists");
144			}
145	
146			if (result.hasErrors()) {
147				return VIEWS_PETS_CREATE_OR_UPDATE_FORM;
148			}
149	
150			try {
151				updatePetDetails(owner, pet);
152			}
153			catch (DataIntegrityViolationException ex) {
154				if (!isDuplicatePetNameViolation(ex)) {
155					throw ex;
156				}
157				result.rejectValue("name", "duplicate", "already exists");
158				return VIEWS_PETS_CREATE_OR_UPDATE_FORM;
159			}
160			redirectAttributes.addFlashAttribute("message", "Pet details has been edited");
161			return "redirect:/owners/{ownerId}";
162		}
163	
164		private boolean isNameTakenByAnotherPet(Owner owner, Pet pet) {
165			if (!StringUtils.hasText(pet.getName())) {
166				return false;
167			}
168			Pet existingPet = owner.getPet(pet.getName(), false);
169			return existingPet != null && !Objects.equals(existingPet.getId(), pet.getId());
170		}
171	
172		/**
173		 * Updates the pet details if it exists or adds a new pet to the owner.
174		 * @param owner The owner of the pet
175		 * @param pet The pet with updated details
176		 */
177		private void updatePetDetails(Owner owner, Pet pet) {
178			Integer id = pet.getId();
179			Assert.state(id != null, "'pet.getId()' must not be null");
180			Pet existingPet = owner.getPet(id);
181			if (existingPet != null) {
182				// Update existing pet's properties
183				existingPet.setName(pet.getName());
184				existingPet.setBirthDate(pet.getBirthDate());
185				existingPet.setType(pet.getType());
186			}
187			else {
188				owner.addPet(pet);
189			}
190			this.owners.saveAndFlush(owner);
191		}
192	
193		private boolean isDuplicatePetNameViolation(DataIntegrityViolationException ex) {
194			String message = ex.getMessage();
195			return message != null && message.toLowerCase().contains("unique_owner_pet_name");
196		}
197	
198	}
